namespace sv_bff03398475a41e1bb2ac12dc016a260.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeState
{
    public ThemeMode Mode { get; set; } = ThemeMode.System;
    public string AccentColor { get; set; } = "#0078d4";
}

using Microsoft.AspNetCore.Components;

namespace sv_bff03398475a41e1bb2ac12dc016a260.Services;

/// <summary>
/// Scoped service that owns the mutable theme state for a single circuit.
/// Components call SetThemeAsync/SetAccentColorAsync to update state and
/// notify all CascadingParameter subscribers app-wide.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeState> _source;

    public ThemeService(CascadingValueSource<ThemeState> source)
    {
        _source = source;
    }

    public ThemeState Current => _source.GetType()
        .GetField("_value", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
        is null ? new ThemeState() : GetCurrentValue();

    // Access the current value through the cascading source
    private ThemeState? _snapshot;

    internal void SetSnapshot(ThemeState state) => _snapshot = state;

    public ThemeState GetCurrent() => _snapshot ?? new ThemeState();

    public async Task SetThemeAsync(ThemeMode mode)
    {
        var state = GetCurrent();
        state.Mode = mode;
        await _source.NotifyChangedAsync(state);
    }

    public async Task SetAccentColorAsync(string color)
    {
        var state = GetCurrent();
        state.AccentColor = color;
        await _source.NotifyChangedAsync(state);
    }

    public async Task UpdateAsync(ThemeMode mode, string accentColor)
    {
        var state = GetCurrent();
        state.Mode = mode;
        state.AccentColor = accentColor;
        await _source.NotifyChangedAsync(state);
    }
}

