arguments.file_text:
@* Displays current theme in the header. Works in static SSR because it receives
   state via [CascadingParameter] from DI-registered CascadingValueSource. *@

<span class="theme-indicator" style="color: @Theme?.AccentColor;">
    @GetIcon() @Theme?.Mode
</span>

@code {
    [CascadingParameter]
    private ThemeState? Theme { get; set; }

    private string GetIcon() => Theme?.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@ThemeService.Current.Mode"
            @onchange="OnThemeChanged">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.Current.AccentColor"
           @onchange="OnColorChanged" />
</div>

<p style="color: @ThemeService.Current.AccentColor;">
    Preview: current accent color applied here.
</p>

@code {
    [CascadingParameter]
    private ThemeState? Theme { get; set; }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            await ThemeService.SetThemeAsync(mode);
        }
    }

    private async Task OnColorChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrEmpty(color))
        {
            await ThemeService.SetAccentColorAsync(color);
        }
    }
}

