using Microsoft.AspNetCore.Components;

namespace sv_bff03398475a41e1bb2ac12dc016a260.Services;

/// <summary>
/// Scoped service (one instance per circuit/user). Holds theme state and
/// raises OnChange so all subscribing components re-render when state changes.
/// </summary>
public class ThemeService
{
    private readonly ThemeState _state = new();

    public ThemeState Current => _state;

    public event Action? OnChange;

    public void SetTheme(ThemeMode mode)
    {
        _state.Mode = mode;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string accentColor)
    {
        _state.AccentColor = accentColor;
        OnChange?.Invoke();
    }

    public void Update(ThemeMode mode, string accentColor)
    {
        _state.Mode = mode;
        _state.AccentColor = accentColor;
        OnChange?.Invoke();
    }
}

