using Microsoft.AspNetCore.Components;
using sv_bff03398475a41e1bb2ac12dc016a260.Components;
using sv_bff03398475a41e1bb2ac12dc016a260.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Theme state: CascadingValueSource crosses render-mode boundaries (static layout → interactive pages)
builder.Services.AddCascadingValue(sp =>
{
    var initialTheme = new ThemeState();
    return new CascadingValueSource<ThemeState>(initialTheme, isFixed: false);
});

// Scoped per circuit — each user gets independent theme state
