arguments.new_str:
@* Displays current theme in the header. Subscribes to ThemeService.OnChange
   so it re-renders whenever any component updates the theme. *@
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.Current.AccentColor;">
    @GetIcon() @ThemeService.Current.Mode
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }

    private string GetIcon() => ThemeService.Current.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };
}

