arguments.new_str:
@* Displays current theme in the header. Must be interactive to receive
   live updates from the scoped ThemeService within the same circuit. *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.Current.AccentColor;">
    @GetIcon() @ThemeService.Current.Mode
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }

    private string GetIcon() => ThemeService.Current.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };
}

